            }
        }
        foreach ((array)($_POST['rows'] ?? []) as $key => $row) {
            $id = ctype_digit((string)$key) ? (int)$key : 0;
            if (!empty($row['_delete'])) {
                if ($id && $permission['pode_excluir']) {
                    $deleteKey = $json(['CODATRIBUICAO' => $id]);
