            $typeId = (int)($row['CODTIPORESPONSABILIDADE'] ?? 0); $destination = strtoupper(trim((string)($row['TIPO_DESTINO'] ?? '')));
            $validTypeIds = array_map('intval', array_column($types, 'CODTIPORESPONSABILIDADE')); $userId = $destination === 'USUARIO' ? max(0, (int)($row['CODUSUARIO'] ?? 0)) : null; $groupId = $destination === 'GRUPO' ? max(0, (int)($row['CODGRUPO'] ?? 0)) : null;
            $validFrom = trim((string)($row['VALIDO_DE'] ?? '')) ?: date('Y-m-d'); $validTo = trim((string)($row['VALIDO_ATE'] ?? '')) ?: null;
            if (!$typeId || !in_array($typeId, $validTypeIds, true) || !in_array($destination, ['USUARIO', 'GRUPO'], true) || ($destination === 'USUARIO' && !$userId) || ($destination === 'GRUPO' && !$groupId)) throw new RuntimeException(IdiomaService::t('licenca_responsabilidades.erro.preencha', ['pt' => 'Preencha finalidade e destino em todas as linhas.', 'en' => 'Fill in purpose and assignee on every row.', 'es' => 'Complete finalidad y destino en todas las líneas.']));
            $data = ['CODMODULO' => $moduleId, 'ORIGEM' => 'DIRETA', 'CODTIPORESPONSABILIDADE' => $typeId, 'CODCATEGORIARESPONSABILIDADE' => null, 'ENTIDADE' => 'li_licencas', 'REGISTRO_ID' => (string)$licenseId, 'TIPO_DESTINO' => $destination, 'CODUSUARIO' => $userId, 'CODGRUPO' => $groupId, 'PRIORIDADE' => (int)($row['PRIORIDADE'] ?? 0), 'PRINCIPAL' => !empty($row['PRINCIPAL']) ? 1 : 0, 'VALIDO_DE' => $validFrom, 'VALIDO_ATE' => $validTo, 'ATIVO' => 1, 'OBSERVACAO' => trim((string)($row['OBSERVACAO'] ?? '')), 'CODUSUARIOALTERACAO' => (int)$_SESSION['usuario']['codusuario']];
            $call($pdo, 'CALL sp_responsabilidade_validar_duplicidade(:atribuicao,:modulo,:origem,:tipo,:categoria,:entidade,:registro,:destino,:usuario,:grupo,:de,:ate)', ['atribuicao' => $id ?: null, 'modulo' => $moduleId, 'origem' => 'DIRETA', 'tipo' => $typeId, 'categoria' => null, 'entidade' => 'li_licencas', 'registro' => (string)$licenseId, 'destino' => $destination, 'usuario' => $userId, 'grupo' => $groupId, 'de' => $validFrom, 'ate' => $validTo]);
            if ($id) { if (!$permission['pode_editar']) continue; $call($pdo, 'CALL sp_crud_update(:tabela,:chave,:dados)', ['tabela' => 'responsabilidade_atribuicoes', 'chave' => $json(['CODATRIBUICAO' => $id]), 'dados' => $json($data)]); }
            else { if (!$permission['pode_incluir']) continue; $call($pdo, 'CALL sp_crud_insert(:tabela,:dados)', ['tabela' => 'responsabilidade_atribuicoes', 'dados' => $json($data)]); }
        }
        $message = (!$permission['pode_editar'] && !$permission['pode_incluir'] && $permission['pode_excluir'])
