<script>document.addEventListener('DOMContentLoaded',function(){var table=document.querySelector('#responsibilityEditTable tbody'),types=<?= json_encode($types, JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES) ?>,users=<?= json_encode($users, JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES) ?>,groups=<?= json_encode($groups, JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES) ?>,seq=0;function opts(items,id,label){return '<option value=""><?= $h('selecione', ['pt' => 'Selecione', 'en' => 'Select', 'es' => 'Seleccione']) ?></option>'+items.map(function(x){return '<option value="'+x[id]+'">'+String(x[label]||'').replace(/</g,'&lt;')+'</option>';}).join('');}function toggle(row){var group=row.querySelector('.js-destination').value==='GRUPO';row.querySelector('.js-user').classList.toggle('d-none',group);row.querySelector('.js-group').classList.toggle('d-none',!group);}document.querySelectorAll('[data-edit-row]').forEach(function(row){toggle(row);row.querySelector('.js-destination').addEventListener('change',function(){toggle(row);});});document.querySelector('#addResponsibility')?.addEventListener('click',function(){var key='novo_'+(++seq),tr=document.createElement('tr');tr.setAttribute('data-edit-row','');tr.setAttribute('data-row-key',key);tr.innerHTML='<td><select class="form-select form-select-sm" name="rows['+key+'][CODTIPORESPONSABILIDADE]">'+types.map(function(x){return '<option value="'+x.CODTIPORESPONSABILIDADE+'">'+x.NOME+'</option>';}).join('')+'</select></td><td><select class="form-select form-select-sm js-destination" name="rows['+key+'][TIPO_DESTINO]"><option value="USUARIO"><?= $h('destino.usuario', ['pt' => 'Usuário', 'en' => 'User', 'es' => 'Usuario']) ?></option><option value="GRUPO"><?= $h('destino.grupo', ['pt' => 'Grupo', 'en' => 'Group', 'es' => 'Grupo']) ?></option></select></td><td><select class="form-select form-select-sm js-user" name="rows['+key+'][CODUSUARIO]">'+opts(users,'CODUSUARIO','NOME')+'</select><select class="form-select form-select-sm js-gro